package com.stackportal.dto.request.tenant;

import com.stackportal.entity.master.TenantStatus;
import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import java.util.UUID;

/**
 * Request payload for creating or updating a tenant.
 *
 * <p>{@code databaseName}, {@code databaseUrl}, and {@code databaseUsername}
 * are intentionally omitted — they are auto-generated by
 * {@link com.stackportal.tenant.provisioning.TenantDatabaseProvisioner}.</p>
 *
 * <p>{@code databasePassword} is optional. When blank, the provisioner falls
 * back to the master credentials configured in {@code application.yml}.</p>
 */
public record TenantRequest(

        @NotBlank
        String name,

        @Size(max = 150)
        String adminName,

        @Email
        String adminEmail,

        UUID logoId,

        @Email
        String email,

        @Size(max = 255, message = "Website must not exceed 255 characters") String website,

        String phone,

        @Size(max = 500, message = "Address must not exceed 500 characters") String address,

        @Size(max = 100, message = "City must not exceed 100 characters") String city,

        @Size(max = 100, message = "Country must not exceed 100 characters") String country,

        @Size(max = 1000, message = "Notes must not exceed 1000 characters") String notes,

        /**
         * Optional password for the tenant database user.
         * If null / blank the master DB password is used instead.
         */
        String databasePassword,

        TenantStatus status
) {
}
